/**
 * Signals in message JETSON_COMMAND.
 *
 * Actuator request from the Jetson. 100 Hz. Rejected by the gateway when the CRC fails, the heartbeat does not advance, or any field is out of range. 50 ms without an accepted frame is an urgent stop.
 *
 * All signal values are as on the CAN bus.
 */
struct mcqueen_jetson_command_t {
    /**
     * Target angle at the front wheels, left positive.
     *
     * Range: -32768..32767 (-3.2768..3.2767 rad)
     * Scale: 0.0001
     * Offset: 0
     */
    int16_t steering_angle;

    /**
     * Range: 0..1000 (0..1 -)
     * Scale: 0.001
     * Offset: 0
     */
    uint16_t throttle;

    /**
     * Range: 0..1000 (0..1 -)
     * Scale: 0.001
     * Offset: 0
     */
    uint16_t brake;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t lat_enable;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t long_enable;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t request_urgent_stop;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t reserved;

    /**
     * Incrementing counter. The gateway accepts an advance of 1 to 5 over the last accepted value so that a single lost frame does not cause a stop, and rejects anything else.
     *
     * Range: 0..65535 (0..65535 -)
     * Scale: 1
     * Offset: 0
     */
    uint16_t heartbeat;

    /**
     * CRC-8 SAE J1850 (poly 0x1D, init 0xFF, xorout 0xFF) over bytes 0 to 6.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t crc;
};

